:root {
  --bg-deep: #071923;
  --bg-mid: #102d3a;
  --bg-water: #0d4860;
  --panel: rgba(11, 25, 35, 0.78);
  --panel-border: rgba(139, 214, 255, 0.42);
  --gold: #ffd166;
  --teal: #7ae7d1;
  --rose: #ff7a90;
  --highlight: #9ad7ff;
  --text: #edf7ff;
  --muted: #bdd7e5;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  height: 100%;
  background:
    radial-gradient(circle at top, rgba(95, 164, 200, 0.25), transparent 35%),
    linear-gradient(180deg, #040d14 0%, var(--bg-deep) 100%);
  color: var(--text);
  font-family: Inter, "Segoe UI", sans-serif;
}

body {
  display: grid;
  place-items: center;
}

.game-shell {
  position: relative;
  width: min(96vw, 960px);
  height: min(92vh, 600px);
  border-radius: 18px;
  overflow: hidden;
  border: 1px solid rgba(182, 232, 255, 0.3);
  background: rgba(10, 19, 26, 0.92);
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
}

canvas {
  display: block;
  width: 100%;
  height: 100%;
  background: linear-gradient(180deg, rgba(17, 61, 73, 0.94), rgba(14, 39, 49, 1));
}

.overlay {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  background: rgba(7, 18, 25, 0.54);
  backdrop-filter: blur(2px);
  transition: opacity 180ms ease;
}

.overlay.hidden {
  opacity: 0;
  pointer-events: none;
}

.overlay.visible {
  opacity: 1;
}

.panel {
  width: min(80%, 560px);
  padding: 28px 26px 22px;
  border-radius: 18px;
  border: 1px solid var(--panel-border);
  background: var(--panel);
  box-shadow: 0 14px 30px rgba(0, 0, 0, 0.28);
}

.eyebrow {
  margin: 0 0 8px;
  font-size: 0.72rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--teal);
}

h1, h2 {
  margin: 0 0 10px;
  line-height: 1.1;
}

h1 {
  font-size: clamp(2.2rem, 4vw, 3.2rem);
}

p {
  margin: 0 0 12px;
  color: var(--muted);
  line-height: 1.6;
}

ul {
  margin: 14px 0 20px;
  padding-left: 18px;
  color: var(--muted);
  line-height: 1.8;
}

button {
  appearance: none;
  border: 1px solid rgba(152, 221, 255, 0.35);
  background: linear-gradient(180deg, rgba(17, 42, 52, 0.96), rgba(10, 27, 34, 0.96));
  color: var(--text);
  border-radius: 12px;
  padding: 12px 16px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: transform 130ms ease, border-color 130ms ease, box-shadow 130ms ease;
}

button:hover {
  transform: translateY(-1px);
  border-color: rgba(150, 220, 255, 0.8);
  box-shadow: 0 0 0 3px rgba(130, 187, 255, 0.12);
}

button:active {
  transform: translateY(0);
}

#startBtn,
.primary {
  background: linear-gradient(180deg, rgba(56, 114, 140, 0.95), rgba(30, 71, 95, 0.95));
}

.shop-panel {
  width: min(82%, 720px);
}

.shop-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(180px, 1fr));
  gap: 14px;
  margin: 18px 0 20px;
}

.upgrade-btn {
  min-height: 90px;
  text-align: left;
  line-height: 1.5;
  padding: 14px 16px;
}

.upgrade-btn span {
  display: block;
  margin-top: 6px;
  font-size: 0.82rem;
  color: var(--muted);
}

.shop-actions {
  display: flex;
  justify-content: flex-end;
}

@media (max-width: 640px) {
  .game-shell {
    width: 100vw;
    height: 100vh;
    border-radius: 0;
  }

  .panel {
    width: min(88%, 540px);
    padding: 22px 18px 18px;
  }

  .shop-grid {
    grid-template-columns: 1fr;
  }
}

