const targets = await fetch('http://127.0.0.1:9222/json/new?http://localhost:3002/', { method: 'PUT' }).then((response) => response.json());
const socket = new WebSocket(targets.webSocketDebuggerUrl);
let nextId = 0;
const pending = new Map();
const errors = [];
socket.addEventListener('message', ({ data }) => {
  const message = JSON.parse(data);
  if (message.method === 'Runtime.exceptionThrown') errors.push(message.params.exceptionDetails.text);
  if (message.id && pending.has(message.id)) {
    pending.get(message.id)(message);
    pending.delete(message.id);
  }
});
await new Promise((resolve, reject) => {
  socket.addEventListener('open', resolve, { once: true });
  socket.addEventListener('error', reject, { once: true });
});
function command(method, params = {}) {
  const id = ++nextId;
  socket.send(JSON.stringify({ id, method, params }));
  return new Promise((resolve) => pending.set(id, resolve));
}
async function evaluate(expression) {
  const result = await command('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  if (result.error || result.result.exceptionDetails) throw new Error(JSON.stringify(result));
  return result.result.result.value;
}
await command('Page.enable');
await command('Runtime.enable');
await command('Page.navigate', { url: 'http://localhost:3002/' });
await new Promise((resolve) => setTimeout(resolve, 600));
const start = await evaluate("document.title + '|' + document.getElementById('overlay').className");
await evaluate("Math.random = () => 0; document.getElementById('startBtn').click(); window.dispatchEvent(new KeyboardEvent('keydown', { key: ' ', bubbles: true })); true");
await new Promise((resolve) => setTimeout(resolve, 100));
await evaluate("window.dispatchEvent(new KeyboardEvent('keyup', { key: ' ', bubbles: true }))");
const started = await evaluate("state.mode + '|' + (state.cast !== null)");
await new Promise((resolve) => setTimeout(resolve, 7000));
const result = await evaluate("JSON.stringify({ mode: state.mode, catches: state.fishCaughtToday, gold: state.gold, cast: !!state.cast, caught: state.message })");
console.log(JSON.stringify({ start, started, result: JSON.parse(result), errors }, null, 2));
socket.close();
process.exit(errors.length ? 1 : 0);

